INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 1, 'Arrive In Paro', 'The first gift from Bhutan will be the cool, clean fresh air as you step off the plane. After visa formalities your guide welcomes you in the traditional way.', 'Airport to hotel: 7 km / 15 to 20 mins', '2,200m / 7,218ft', '["Welcome at Paro airport","Gear check and route briefing","Meet your trek crew"]', 'Overnight at the hotel in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 2, 'Paro To Shana', 'A short drive to Drukgyel Dzong, then the trek begins along the Pa Chhu through terraced fields and thick forest to camp at Shana.', 'Trek: 5 to 6 hrs / 15 km', 'Shana 2,820m / 9,252ft', '["Drukgyel Dzong","Pa Chhu river valley","Army outpost at Gunitsawa (permits checked)"]', 'Overnight in camp at Shana (2,820m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 3, 'Shana To Soi Thangthangka', 'A long day up the river valley, climbing gradually through rhododendron and conifer forest to a camp in a meadow.', 'Trek: 7 to 8 hrs / 22 km', 'Soi Thangthangka 3,610m / 11,844ft', '["River valley with mixed forest","Rhododendron and bamboo groves","Yak-herder meadows"]', 'Overnight in camp at Soi Thangthangka (3,610m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 4, 'Soi Thangthangka To Jangothang', 'The valley opens and Mount Jomolhari appears. Camp beneath the mountain at Jangothang, with the ruins of an old dzong beside you.', 'Trek: 5 to 6 hrs / 19 km', 'Jangothang 4,040m / 13,255ft', '["First view of Mount Jomolhari","Ruins of the old Jangothang dzong","Camp at the base of the mountain"]', 'Overnight in camp at Jangothang (4,040m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 5, 'Rest Day At Jangothang', 'A rest day to acclimatise. Optional hikes to Tshophu Lake or up the ridge for wide views of Jomolhari, Jichu Drake and Tserim Kang.', 'Trek: 3 to 4 hrs optional day hike', 'Jangothang 4,040m / 13,255ft', '["Tshophu Lake","Views of Jomolhari and Jichu Drake","Time with local yak herders"]', 'Overnight in camp at Jangothang (4,040m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 6, 'Jangothang To Lingshi', 'Cross the Nyile La and drop into the high valley of Lingshi, with Lingshi Dzong visible on the ridge as you arrive.', 'Trek: 7 to 8 hrs / 18 km', 'Nyile La 4,870m / 15,978ft; Lingshi 4,010m / 13,156ft', '["Nyile La Pass","Lingshi Dzong","Views of Tserim Kang"]', 'Overnight in camp at Lingshi (4,010m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 7, 'Lingshi To Shodu', 'Cross the Yale La and drop to Shodu through yak pastures and a rhododendron forest.', 'Trek: 7 to 8 hrs / 22 km', 'Yale La 4,820m / 15,814ft; Shodu 4,080m / 13,386ft', '["Yale La Pass","High pastures and blue sheep country"]', 'Overnight in camp at Shodu (4,080m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 8, 'Shodu To Barshong', 'A gentler day following the river downhill through dense forest to a camp at Barshong.', 'Trek: 6 to 7 hrs / 15 km', 'Barshong 3,590m / 11,778ft', '["Barshong Dzong ruins","River valley forest"]', 'Overnight in camp at Barshong (3,590m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'jomolhari-trek'), 9, 'Barshong To Dodina And Thimphu', 'The final walk of the trek takes you out to Dodina, where your vehicle waits for the drive to Thimphu.', 'Trek: 5 hrs / 15 km, then drive to Thimphu', 'Dodina 2,640m / 8,661ft', '["Dolam Kencho","Cheri Monastery (optional)","Dinner celebration in Thimphu"]', 'Overnight at the hotel in Thimphu');
