INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'the-snowman-trek'), 20, 'Thanza To Tshochena', 'A long climb to a lakeside camp beneath the snow peaks.', 'Trek: 6 to 7 hrs / 17 km', 'Tshochena 4,970m / 16,306ft', '["Glacial lakes","Snow peaks"]', 'Overnight in camp at Tshochena (4,970m)');
