INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'the-snowman-trek'), 22, 'Jichu Dramo To Chukarpo', 'Descend through valleys of dwarf rhododendron to a quiet camp.', 'Trek: 6 to 7 hrs / 17 km', 'Chukarpo 3,500m / 11,483ft', '["Waterfalls","Alpine forest"]', 'Overnight in camp at Chukarpo (3,500m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'the-snowman-trek'), 23, 'Chukarpo To Duer And Sephu', 'The last stage descends to Duer hot springs, where a soak is the reward for three weeks of walking.', 'Trek: 7 to 8 hrs / 18 km', 'Duer 3,300m / 10,827ft', '["Duer hot springs","Last night on the trail"]', 'Overnight in camp at Duer (3,300m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'the-snowman-trek'), 24, 'Drive To Bumthang And Departure', 'Your vehicle meets you at the road head for the drive to Bumthang and onward arrangements.', 'Sephu to Bumthang: about 3 hrs', '2,600m / 8,530ft', '["Jambay Lhakhang","Celebration dinner in Bumthang"]', 'Overnight at the hotel in Bumthang');
