INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 1, 'Arrive In Paro, Drive To Thimphu', 'The first gift from Bhutan will be the cool, clean fresh air as you step off the plane. After visa formalities your guide welcomes you in the traditional way.', '54 km / 1 to 1.5 hrs', '2,320m / 7,612ft', '["Welcome at Paro airport","Memorial Chorten"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 2, 'Thimphu To Geynekha And Gur', 'Drive to Geynekha, the trailhead, and begin the walk up through rhododendron forest to camp at Gur.', 'Trek: 3 to 4 hrs / 6 km', 'Gur 3,950m / 12,959ft', '["Geynekha trailhead","Rhododendron forest","First views of the lakes"]', 'Overnight in camp at Gur (3,950m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 3, 'Gur To Labatama', 'Climb above the tree line to Labatama and its string of lakes, with views of the high peaks on a clear day.', 'Trek: 5 to 6 hrs / 10 km', 'Labatama 4,150m / 13,615ft', '["Alpine lakes of the Dagala range","Views of Gangkhar Puensum and Jomolhari"]', 'Overnight in camp at Labatama (4,150m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 4, 'Labatama To Panka', 'Cross the highlands past more lakes and descend to Panka, a quiet campsite.', 'Trek: 5 to 6 hrs / 12 km', 'High pass 4,720m / 15,486ft; Panka 3,850m / 12,631ft', '["Dagala highlands","Yak herders’ camps"]', 'Overnight in camp at Panka (3,850m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 5, 'Panka To Talakha And Thimphu', 'A final descent through rhododendron forest to Talakha, where your vehicle waits for the drive back to Thimphu.', 'Trek: 4 to 5 hrs / 11 km, then drive to Thimphu', 'Talakha 3,080m / 10,105ft', '["Talakha Monastery","Celebration dinner in Thimphu"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek'), 6, 'Departure', 'A relaxed morning before your private transfer to Paro International Airport for your onward flight.', 'Thimphu to Paro airport: 54 km / 1 to 1.5 hrs', '2,235m / 7,333ft', '["Private transfer to Paro International Airport"]', '');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumdra-trek'), 1, 'Arrive In Paro And Trek To Bumdra', 'After a welcome at Paro airport, drive to the trailhead and begin the climb through pine forest to camp near Bumdra Monastery.', 'Trek: 4 to 5 hrs / 6 km (a climb of about 1,200m)', 'Bumdra 3,800m / 12,467ft', '["Forest trail with prayer flags","Hermitages along the route","Sunset over the Paro valley"]', 'Overnight in camp at Bumdra (3,800m)');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumdra-trek'), 2, 'Bumdra To Taktsang And Paro', 'Visit Bumdra Monastery in the morning, walk along the ridge and descend to Tiger’s Nest, then on to the road.', 'Trek: 5 to 6 hrs / 8 km', 'Bumdra 3,800m / 12,467ft to Taktsang 3,120m / 10,236ft', '["Bumdra Monastery","The ridge walk above Taktsang","Taktsang (Tiger’s Nest) Monastery","Private blessing with a monk"]', 'Overnight at the hotel in Paro');
