-- Full tour pages + detailed itineraries for the trekking tours (and trek details for the Druk Path days). Idempotent.
-- Local: npm run db:trekking-pages:local   Remote: wrangler d1 execute altara-db --remote --file=seed-trekking-pages.sql

UPDATE itinerary_days SET driving = 'Airport to hotel: 7 km / 15 to 20 mins', elevation = '2,200m / 7,218ft', attractions = '["Meet your trek crew","Gear check and route briefing"]', overnight = 'Overnight at the hotel in Paro' WHERE day_number = 1 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');
UPDATE itinerary_days SET driving = 'Trek: 4 to 5 hrs / 6 km (a climb of about 900m)', elevation = 'Jele Dzong 3,480m / 11,417ft', attractions = '["Blue pine and rhododendron forest","The ruins of Jele Dzong","First views back over the Paro valley"]', overnight = 'Overnight in camp at Jele Dzong (3,480m)' WHERE day_number = 2 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');
UPDATE itinerary_days SET driving = 'Trek: 3 to 4 hrs / 10 km', elevation = 'Jangchulakha 3,780m / 12,402ft', attractions = '["Ridge walk through rhododendron forest","Yak pastures","Mount Jomolhari on a clear day"]', overnight = 'Overnight in camp at Jangchulakha (3,780m)' WHERE day_number = 3 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');
UPDATE itinerary_days SET driving = 'Trek: 5 to 6 hrs / 11 km', elevation = 'Jimilang Tsho 3,880m / 12,730ft', attractions = '["Jimilang Tsho, the trek''s largest lake","Giant trout, known locally"]', overnight = 'Overnight in camp at Jimilang Tsho (3,880m)' WHERE day_number = 4 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');
UPDATE itinerary_days SET driving = 'Trek: 6 to 7 hrs / 14 km', elevation = 'Phume La 4,210m / 13,812ft; camp 3,750m / 12,303ft', attractions = '["Phume La, the trek''s high point","Simkotra Tsho","Phajoding Monastery area"]', overnight = 'Overnight in camp at Phajoding (3,750m)' WHERE day_number = 5 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');
UPDATE itinerary_days SET driving = 'Trek: 3 to 4 hrs / 5 km, then drive to Thimphu', elevation = '2,320m / 7,612ft', attractions = '["Phajoding Monastery","A descent into Thimphu on foot"]', overnight = '' WHERE day_number = 6 AND tour_id = (SELECT id FROM tours WHERE slug = 'druk-path-trek');

UPDATE tours SET has_page = 1, summary = 'Nine days beneath Mount Jomolhari, Bhutan''s sacred 7,326m peak — yak pastures, high lakes and a chance to see the Himalaya at close range.', overview_title = 'Jomolhari Trek Overview', overview = 'The Jomolhari Trek is the classic Bhutan trek for people who want to be in the high Himalaya without committing to three weeks. From the head of the Paro valley the trail climbs along the Pa Chhu to Jangothang, a camp directly under the white face of Jomolhari, a mountain no one has ever been allowed to climb because it is sacred to the people of the valley.

From Jangothang you cross high passes of almost 4,900 metres into the remote Lingshi region and descend through Shodu and Barshong back to Thimphu. Along the way you meet yak herders in black felt tents, camp beside turquoise lakes, and walk in a landscape where days go by without another trekker. A rest day at Jangothang lets you acclimatise and explore.', highlights = '["Camp at Jangothang, directly beneath Mount Jomolhari (7,326m)","A rest day for acclimatisation and a hike to Tshophu Lake","Cross the Nyile La and Yale La, passes near 4,900m","Meet yak herders in the high pastures of Lingshi","Views of Jichu Drake, Tserim Kang and other peaks","Finish in Thimphu after a final walk through Dodina"]', facts = '[{"icon":"pin","label":"Region","value":"Paro Valley, Jomolhari & Lingshi"},{"icon":"clock","label":"Duration","value":"9 Days / 8 Nights"},{"icon":"mountain","label":"Max Altitude","value":"4,890m — highest pass"},{"icon":"sun","label":"Best Season","value":"April–June & September–November"},{"icon":"difficulty","label":"Difficulty","value":"Moderate to Challenging"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle to the trailhead and from the end point"}]', facts_note = 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', pack_title = 'What To Pack For The Jomolhari Trek', pack_text = 'Camps go above 4,000m, where nights are below freezing even in good weather. Bring a four-season sleeping bag rated to at least -10°C, a down jacket, waterproof shell, thermal layers, gloves, a warm hat and sturdy broken-in hiking boots.

Trekking poles, a headlamp, sun protection, a water bottle and a personal first-aid kit complete the list. Your crew carries tents, kitchen and food on pack animals, so you only need a daypack for the walking day.', inclusions = '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', exclusions = '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', extras_title = 'Trek Cost Includes', extras = '["One guide","Cook and helpers","Ponies or yaks for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', inclusions_note = 'Note: For this trek, a load of 15kg per person is allowed.', faqs = '[{"question":"How hard is the Jomolhari Trek?","answer":"Moderate to challenging. The days are 5–8 hours of walking and the route crosses two passes near 4,900m, so reasonable fitness and the rest day for acclimatisation matter."},{"question":"Will we see Mount Jomolhari?","answer":"Often, yes — Jangothang sits directly beneath it, and clear mornings are common in the spring and autumn seasons. Cloud can build in the afternoons."},{"question":"Do I need a trekking permit?","answer":"Yes. A permit is required and is arranged for you as part of the package, together with your Sustainable Development Fee."}]', districts = '["Paro","Thimphu"]', cost_title = 'Trek Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', seo_description = 'Nine days beneath Mount Jomolhari, Bhutan''s sacred 7,326m peak — yak pastures, high lakes and a chance to see the Himalaya at close range.', updated_at = datetime('now') WHERE slug = 'jomolhari-trek';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'jomolhari-trek');

UPDATE tours SET has_page = 1, summary = 'Bhutan''s most demanding trek: 24 days across the roof of the Kingdom, through Laya and Lunana to the foot of the world''s highest unclimbed peaks.', overview_title = 'The Snowman Trek Overview', overview = 'The Snowman Trek is the great walk of Bhutan and one of the hardest treks in the Himalaya. It crosses eleven high passes, several above 5,000 metres, through the remote regions of Laya and Lunana, where villages are reached only on foot and life follows the yak calendar. Fewer people complete it each year than climb Everest.

The trail begins like the Jomolhari trek, then continues north to Laya, home of the Layap people in their conical bamboo hats, and into Lunana, a high-altitude world of glacial lakes and remote settlements before descending to Bumthang. It is a long expedition that rewards patience, fitness and a willingness to adjust the plan to the weather, and the best window is short.', highlights = '["Cross eleven high passes, including Rinchen Zoe La at 5,320m","The Layap people of Laya in their conical bamboo hats","Lunana: glacial lakes and villages beyond the road","Views of Gangkhar Puensum, the highest unclimbed mountain in the world","Camp beneath Jomolhari and Jichu Drake","Natural hot springs at Duer"]', facts = '[{"icon":"pin","label":"Region","value":"Paro, Laya, Lunana & Bumthang"},{"icon":"clock","label":"Duration","value":"24 Days / 23 Nights"},{"icon":"mountain","label":"Max Altitude","value":"5,320m — Rinchen Zoe La"},{"icon":"sun","label":"Best Season","value":"September–October (the weather window is short)"},{"icon":"difficulty","label":"Difficulty","value":"Very Challenging"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle to the trailhead and from the end point"}]', facts_note = 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', pack_title = 'What To Pack For The Snowman Trek', pack_text = 'This is a high-altitude expedition: temperatures drop well below freezing and snow is possible at any time. You will need a sleeping bag rated to -15°C, a down jacket, waterproof shell and trousers, thermal layers, insulated gloves, a warm hat, gaiters and broken-in, waterproof hiking boots.

Bring trekking poles, a headlamp with spare batteries, sun protection, water purification, and a thorough personal first-aid kit. Your crew carries tents, kitchen and food on yaks and ponies, so you only need a daypack for the walking day. Insurance covering helicopter evacuation is essential.', inclusions = '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', exclusions = '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', extras_title = 'Trek Cost Includes', extras = '["One guide","Cook and helpers","Ponies or yaks for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', inclusions_note = 'Note: For this trek, a load of 15kg per person is allowed.', faqs = '[{"question":"How difficult is the Snowman Trek?","answer":"Very challenging. It averages 6–8 hours of walking a day, crosses passes above 5,000m and has few exit points. Strong fitness, previous high-altitude trekking and a flexible mindset all help."},{"question":"Why does only a minority finish?","answer":"Early snow, altitude sickness and the length of the trek all play a part. We build in rest days and a weather buffer, but reaching the end is never guaranteed."},{"question":"When is the best time?","answer":"September and October, when the passes are usually clear. Spring can work in some years but snow often blocks the highest passes."}]', districts = '["Paro","Thimphu","Gasa","Bumthang"]', cost_title = 'Trek Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', seo_description = 'Bhutan''s most demanding trek: 24 days across the roof of the Kingdom, through Laya and Lunana to the foot of the world''s highest unclimbed peaks.', updated_at = datetime('now') WHERE slug = 'the-snowman-trek';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'the-snowman-trek');

UPDATE tours SET has_page = 1, summary = 'Sixteen days from Paro to Gasa through the Jomolhari highlands and the Layap villages, ending at natural hot springs.', overview_title = 'Laya Gasa Trek Overview', overview = 'The Laya Gasa Trek combines two of Bhutan''s finest walking regions into one long journey. It begins on the Jomolhari trail beneath one of the Himalaya''s great peaks, crosses several high passes, then follows the ridge north to Laya, the home of the Layap and the highest permanent settlement in Bhutan.

From Laya the route descends through forests to Gasa, ending at the Gasa Tshachu hot springs before you drive on to Punakha. It is a long, varied trek that moves from glaciers to rhododendron forest and from yak herders to subtropical valleys, and it is the best way to see the length of the high Himalaya without the extreme altitude of the Snowman.', highlights = '["Camp beneath Mount Jomolhari at Jangothang","Cross the Nyile La, Gogu La and Jare La passes","Meet the Layap people in their conical bamboo hats at Laya","Walk down through rhododendron forest to Gasa","Soak in the Gasa Tshachu hot springs at the end","A rest day in Laya to explore village life"]', facts = '[{"icon":"pin","label":"Region","value":"Paro, Laya & Gasa"},{"icon":"clock","label":"Duration","value":"16 Days / 15 Nights"},{"icon":"mountain","label":"Max Altitude","value":"4,750m — highest point on the trail"},{"icon":"sun","label":"Best Season","value":"April–June & September–November"},{"icon":"difficulty","label":"Difficulty","value":"Challenging"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle to the trailhead and from the end point"}]', facts_note = 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', pack_title = 'What To Pack For The Laya Gasa Trek', pack_text = 'Camps reach nearly 4,300m and nights are below freezing at the higher ones. Bring a sleeping bag rated to -10°C, a down jacket, waterproof shell, thermal layers, gloves, a warm hat and broken-in hiking boots with good ankle support.

Trekking poles are useful on the long descents. Bring a headlamp, sun protection, a water bottle with purification tablets and a personal first-aid kit. Your crew carries tents, kitchen and food on pack animals.', inclusions = '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', exclusions = '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', extras_title = 'Trek Cost Includes', extras = '["One guide","Cook and helpers","Ponies or yaks for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', inclusions_note = 'Note: For this trek, a load of 15kg per person is allowed.', faqs = '[{"question":"How hard is the Laya Gasa Trek?","answer":"Challenging. Expect 5–8 hours of walking a day at altitude, with several passes close to 4,800m. Good fitness and the built-in rest days make it achievable for experienced hikers."},{"question":"What is Laya like?","answer":"A high village of stone and slate houses where women wear black yak-hair dresses and conical bamboo hats. It has a school, a clinic and a way of life shaped by yaks and the seasons."},{"question":"Where does the trek end?","answer":"At the Gasa hot springs, after which you drive to Punakha and on to Thimphu or Paro for your onward flight."}]', districts = '["Paro","Thimphu","Gasa","Punakha"]', cost_title = 'Trek Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', seo_description = 'Sixteen days from Paro to Gasa through the Jomolhari highlands and the Layap villages, ending at natural hot springs.', updated_at = datetime('now') WHERE slug = 'laya-gasa-trek';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'laya-gasa-trek');

UPDATE tours SET has_page = 1, summary = 'Six days in the high lake country above Thimphu — a short, scenic trek past alpine lakes with views of Gangkhar Puensum and Jomolhari.', overview_title = 'Dagala Thousand Lakes Trek Overview', overview = 'The Dagala Thousand Lakes Trek is a short route in the hills above Thimphu, well suited to anyone who wants a high-altitude walk without the length of a major trek. The trail winds through rhododendron and juniper forest to a plateau scattered with glacial lakes — the Dagala Thousand Lakes — the largest group of high lakes in the western half of Bhutan.

On clear days the ridges reveal views of Gangkhar Puensum, Jomolhari and Jichu Drake. You camp beside lakes, walk through yak pastures and meet the herders who spend their summers in the high valleys. The trek begins and ends near Thimphu, so there is no need for long drives or a separate return trip.', highlights = '["Camp beside glacial lakes on the Dagala plateau","Views of Gangkhar Puensum, Jomolhari and Jichu Drake","Rhododendron and juniper forest in the lower valleys","Yak herders’ summer camps","A short, accessible route close to Thimphu","A city dinner at the end of the trek"]', facts = '[{"icon":"pin","label":"Region","value":"Thimphu Highlands"},{"icon":"clock","label":"Duration","value":"6 Days / 5 Nights"},{"icon":"mountain","label":"Max Altitude","value":"4,720m — Dagala highlands"},{"icon":"sun","label":"Best Season","value":"March–May & October–November"},{"icon":"difficulty","label":"Difficulty","value":"Moderate"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle to the trailhead and from the end point"}]', facts_note = 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', pack_title = 'What To Pack For The Dagala Trek', pack_text = 'Camps are around 4,000m, so nights can be below freezing even outside winter. Bring a sleeping bag rated to -5°C or colder, a down jacket, waterproof shell, thermal layers, gloves and a warm hat.

Wear broken-in hiking boots, and bring trekking poles, a headlamp, sun protection and a personal first-aid kit. Your crew carries tents, kitchen equipment and food on pack animals.', inclusions = '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', exclusions = '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', extras_title = 'Trek Cost Includes', extras = '["One guide","Cook and helpers","Ponies or yaks for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', inclusions_note = 'Note: For this trek, a load of 15kg per person is allowed.', faqs = '[{"question":"How hard is the Dagala Thousand Lakes Trek?","answer":"Moderate. The days are 4–6 hours of walking with a few steep sections, and altitude is the main challenge. Previous trekking experience is helpful."},{"question":"When is the best time?","answer":"March to May and October to November for clear skies; spring brings rhododendron blooms. Monsoon months are wet and cloudy."},{"question":"Is it a good first trek?","answer":"Yes, for reasonably fit walkers. It is shorter than the major treks and starts close to Thimphu, but you will still be above 4,000m."}]', districts = '["Thimphu","Paro"]', cost_title = 'Trek Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', seo_description = 'Six days in the high lake country above Thimphu — a short, scenic trek past alpine lakes with views of Gangkhar Puensum and Jomolhari.', updated_at = datetime('now') WHERE slug = 'dagala-thousand-lakes-trek';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'dagala-thousand-lakes-trek');

UPDATE tours SET has_page = 1, summary = 'A three-day trek above Paro to Bumdra Monastery and the cliffs above Tiger’s Nest — the best view of Bhutan’s most famous monastery.', overview_title = 'Bumdra Trek Overview', overview = 'The Bumdra Trek is a short, high-altitude walk above Paro that ends at Tiger''s Nest Monastery from the top. Instead of the usual climb from the valley floor, you follow forest trails to the ridge, camp near Bumdra Monastery, and approach Taktsang from above with views that most visitors never see.

It is a good trek for people with only a few days, and an ideal first night under canvas in Bhutan. The route passes small hermitages, prayer flags and pine forest, and on a clear morning the Paro valley, Jomolhari and the whole Himalayan arc are visible from the camp. The way down ends with the classic view of Taktsang before you reach the road.', highlights = '["Camp near Bumdra Monastery at 3,800m","Approach Tiger’s Nest from above, with a view few visitors see","Pine and rhododendron forest, hermitages and prayer flags","Sunrise views over the Paro valley and the Himalaya","A short trek that fits into a three-day stay","Finish with a private blessing at Tiger’s Nest"]', facts = '[{"icon":"pin","label":"Region","value":"Paro Valley"},{"icon":"clock","label":"Duration","value":"3 Days / 2 Nights"},{"icon":"mountain","label":"Max Altitude","value":"3,800m — Bumdra"},{"icon":"sun","label":"Best Season","value":"March–June & September–November"},{"icon":"difficulty","label":"Difficulty","value":"Easy to Moderate"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle to the trailhead and from the end point"}]', facts_note = 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', pack_title = 'What To Pack For The Bumdra Trek', pack_text = 'Camp is at 3,800m, so evenings are cold. Bring a sleeping bag rated to 0°C or colder, a warm jacket, waterproof shell, gloves and a hat, plus comfortable hiking boots with good grip for the descent.

Bring a headlamp, sun protection, a water bottle and a small daypack. Your crew carries tents and food.', inclusions = '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', exclusions = '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', extras_title = 'Trek Cost Includes', extras = '["One guide","Cook and helpers","Ponies or yaks for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', inclusions_note = 'Note: For this trek, a load of 15kg per person is allowed.', faqs = '[{"question":"Is the Bumdra Trek hard?","answer":"It is a steady climb of 4–5 hours on day one, but short compared with the major treks. Reasonably fit walkers will find it comfortable."},{"question":"How does it differ from the usual Tiger’s Nest hike?","answer":"The standard hike climbs from the valley. The Bumdra route climbs to a ridge, camps near a monastery and reaches Tiger’s Nest from above, with a very different view."},{"question":"Can I combine it with a cultural tour?","answer":"Yes. It combines well with the [Tiger’s Nest Pilgrimage](/tours/tigers-nest-pilgrimage) or the [Royal Capital Immersion](/tours/royal-capital-immersion)."}]', districts = '["Paro"]', cost_title = 'Trek Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', seo_description = 'A three-day trek above Paro to Bumdra Monastery and the cliffs above Tiger’s Nest — the best view of Bhutan’s most famous monastery.', updated_at = datetime('now') WHERE slug = 'bumdra-trek';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'bumdra-trek');
